const e=[{id:"barbell-bench-press",name_en:"Barbell Bench Press",name_es:"Press de banca con barra",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"barbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lie with your eyes under the bar, feet planted, and grip slightly wider than shoulder width.","Pinch your shoulder blades together and keep a slight arch, with glutes and head on the bench.","Lower the bar under control to your lower chest, then press up and slightly back.","Don't flare your elbows to 90 degrees; keep them about 45-70 degrees from your torso on the way down.","Use safety arms or a spotter whenever you train close to failure."],aliases:["bb-bench-press"],origin:"existing"},{id:"incline-barbell-bench-press",name_en:"Barbell Bench Press (Incline)",name_es:"Press de banca con barra (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"barbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the bench to a moderate incline and lie down with the bar roughly over your eyes.","Keep your shoulder blades pulled back and chest up without lifting your glutes off the seat.","Lower the bar to your upper chest, just below the collarbones, and press straight up.","Don't set the incline too steep, or it turns into a shoulder press.","Unrack and rerack the bar with locked-out arms, never with bent elbows."],aliases:["bb-press"],origin:"existing"},{id:"decline-bb-press",name_en:"Barbell Bench Press (Decline)",name_es:"Press de banca con barra (declinado)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"barbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Hook your feet securely under the rollers before lying back on the decline bench.","Keep your shoulder blades squeezed together and your head on the bench throughout.","Lower the bar to your lower chest and press until your arms are straight without slamming into lockout.","Don't bounce the bar off your sternum to get it moving.","Get a spotter to hand off and rerack: the decline angle makes it hard to rack the bar alone."],aliases:[],origin:"existing"},{id:"incline-dumbbell-press",name_en:"Dumbbell Bench Press (Incline)",name_es:"Press de banca con mancuernas (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"dumbbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit on the incline bench with dumbbells on your thighs and kick them up with your knees as you lie back.","Keep your chest up and wrists straight, stacked directly over your elbows.","Lower the dumbbells beside your upper chest, then press up, bringing them slightly together at the top.","Don't clank the dumbbells together or lose tension at the top.","When done, bring the dumbbells to your chest and sit up with them on your thighs instead of dropping them."],aliases:[],origin:"existing"},{id:"db-press-neutral-grip",name_en:"Dumbbell Bench Press (Incline, Neutral Grip)",name_es:"Press de banca con mancuernas (inclinado, agarre neutro)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"dumbbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lie on the incline bench with palms facing each other and the dumbbells over your chest.","Keep your elbows close to your torso and forearms vertical throughout the rep.","Lower until the dumbbells brush the sides of your chest, then press up under control.","Don't rotate your wrists mid-rep; keep your palms facing each other the whole time.","Pick a weight you can control on the way down; if the dumbbells drift or wobble, go lighter."],aliases:[],origin:"existing"},{id:"close-grip-bench-press",name_en:"Barbell Bench Press (Close Grip)",name_es:"Press de banca con barra (agarre cerrado)",body_region:"Chest",primary_muscles:["Triceps","Chest"],secondary_muscles:["Front Delts"],equipment:"barbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip the bar with hands about shoulder-width apart, no narrower.","Keep your elbows tucked close to your body and wrists stacked over your forearms.","Lower the bar to your lower chest and lock out by driving through your triceps.","Don't bring your hands too close: it loads your wrists without hitting the triceps any harder.","Set safety pins just below chest height if you train without a spotter."],aliases:["close-grip-press"],origin:"existing"},{id:"close-grip-decline-press",name_en:"Barbell Bench Press (Decline, Close Grip)",name_es:"Press de banca con barra (declinado, agarre cerrado)",body_region:"Chest",primary_muscles:["Triceps","Chest"],secondary_muscles:["Front Delts"],equipment:"barbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lock your feet under the decline bench rollers and grip the bar about shoulder-width apart.","Keep your elbows close to your torso and your head on the bench for the whole set.","Lower the bar to your lower chest and press up until your elbows are fully extended.","Don't let your elbows flare out as you press.","Train with a spotter who can help you unrack and rerack the bar in this position."],aliases:[],origin:"existing"},{id:"plate-loaded-chest-press-wide-grip",name_en:"Plate-Loaded Chest Press (Wide Grip)",name_es:"Press de pecho en máquina de discos (agarre ancho)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"plate-loaded",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Adjust the seat so the wide handles line up with your mid-chest.","Keep your back and head against the pad with your shoulder blades pinned back.","Press the handles forward without locking your elbows, then return slowly until you feel a stretch.","Don't let your shoulders roll off the pad at the end of the press.","Load and unload plates evenly on both sides of the machine."],aliases:[],origin:"existing"},{id:"wide-grip-chest-press",name_en:"Machine Chest Press (Wide Grip)",name_es:"Press de pecho en máquina (agarre ancho)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"machine",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the seat height so the wide handles sit level with your mid-chest.","Keep your back firmly against the pad and your chest up throughout.","Press until your arms are almost straight, then return slowly until your hands reach chest level.","Don't let the weight stack touch down between reps; keep constant tension.","Make sure the weight pin is fully inserted before you start the set."],aliases:[],origin:"existing"},{id:"mid-cable-fly",name_en:"Cable Fly (Mid Height)",name_es:"Aperturas en polea (altura media)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the pulleys at chest height and step forward into a staggered stance.","Keep a slight, fixed bend in your elbows and your torso steady, with no rocking.","Bring your hands together in front of your chest in a wide arc, then return under control to a stretch.","Don't turn the fly into a press by bending and straightening your elbows.","Don't let your arms travel behind your body line if you feel strain in the shoulder."],aliases:[],origin:"existing"},{id:"high-cable-fly",name_en:"Cable Fly (High to Low)",name_es:"Aperturas en polea (de arriba hacia abajo)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the pulleys at the highest position and stagger your feet for a stable base.","Lean your torso slightly forward and keep your chest open.","Sweep your hands down and in to hip height, then let them rise back slowly.","Don't round your shoulders forward as your hands come together.","Use a weight that lets you control the return without the cables yanking your arms back."],aliases:[],origin:"existing"},{id:"decline-dumbbell-fly",name_en:"Dumbbell Fly (Decline)",name_es:"Aperturas con mancuernas (declinado)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Secure your feet on the decline bench and press the dumbbells over your chest, palms facing in.","Keep a slight, fixed bend in your elbows for the entire set.","Open your arms in an arc until you feel a chest stretch, then bring them back together over your sternum.","Don't lower the dumbbells below the level of the bench.","Start light: dumbbells are harder to control on a decline."],aliases:[],origin:"existing"},{id:"close-grip-dips",name_en:"Dip (Close Grip)",name_es:"Fondos en paralelas (agarre cerrado)",body_region:"Chest",primary_muscles:["Triceps"],secondary_muscles:["Chest","Front Delts"],equipment:"bodyweight",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Support yourself on narrow parallel bars with arms locked out and body upright.","Keep your torso tall and elbows pointing back, tucked close to your sides.","Lower until your elbows reach about 90 degrees, then press back up to full extension.","Don't let your shoulders shrug up toward your ears at the bottom.","Only go as deep as you can control without discomfort at the front of the shoulder."],aliases:[],origin:"existing"},{id:"smith-machine-bench-press",name_en:"Smith Machine Bench Press",name_es:"Press de banca en máquina Smith",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"smith-machine",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Position the bench so the bar comes down right on your lower chest.","Pinch your shoulder blades together and plant your feet firmly on the floor.","Twist to unrack, lower under control to your chest, and press straight up.","Don't set the bench too far up or back: the bar should land on your chest, not your neck.","Set the Smith machine safety stops just above chest height before you start."],aliases:[],origin:"new"},{id:"smith-machine-bench-press-incline",name_en:"Smith Machine Bench Press (Incline)",name_es:"Press de banca en máquina Smith (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"smith-machine",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Position the incline bench so the bar travels down to your upper chest.","Keep your shoulder blades retracted and your glutes on the seat.","Lower the bar until it touches just below your collarbones, then press with steady force.","Don't lift your back off the bench to move more weight.","Rotate the hooks to lock the bar in as soon as you finish your last rep."],aliases:[],origin:"new"},{id:"dumbbell-bench-press",name_en:"Dumbbell Bench Press",name_es:"Press de banca con mancuernas",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"dumbbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with dumbbells on your thighs and kick them to your chest with your knees as you lie back.","Keep your shoulder blades together and forearms vertical over your elbows.","Lower the dumbbells to the sides of your chest and press up in a slight arc toward the middle.","Don't let the dumbbells drift toward your head or feet as you lower them.","If you fail a rep, bring the dumbbells to your chest and sit up instead of dropping them out wide."],aliases:[],origin:"new"},{id:"dumbbell-bench-press-decline",name_en:"Dumbbell Bench Press (Decline)",name_es:"Press de banca con mancuernas (declinado)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"dumbbell",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lock your feet on the decline bench with the dumbbells resting on your chest before lying back.","Keep your head on the bench and wrists firm, stacked over your elbows.","Lower the dumbbells toward your lower chest and press until your arms are nearly straight.","Don't over-arch your back to grind the weight up.","Have a partner hand you the dumbbells if getting them into position on the decline is awkward."],aliases:[],origin:"new"},{id:"machine-chest-press-incline",name_en:"Machine Chest Press (Incline)",name_es:"Press de pecho en máquina (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"machine",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Adjust the seat so the handles line up with your upper chest.","Keep your back and head against the pad and your chest open.","Press up and forward without locking your elbows, then return slowly to the start.","Don't shrug your shoulders toward your ears as you press.","Check that the seat is locked in place before loading any weight."],aliases:[],origin:"new"},{id:"plate-loaded-chest-press-incline",name_en:"Plate-Loaded Chest Press (Incline)",name_es:"Press de pecho en máquina de discos (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts","Triceps"],equipment:"plate-loaded",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with the handles at upper-chest height and your feet flat on the floor.","Keep your shoulder blades together and your back pressed into the pad.","Press the machine arms up, then lower under control until you feel a stretch.","Don't lower so fast that the plates crash at the bottom of the rep.","Strip plates evenly from both sides so the machine doesn't tip out of balance."],aliases:[],origin:"new"},{id:"dumbbell-fly",name_en:"Dumbbell Fly",name_es:"Aperturas con mancuernas",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Lie on a flat bench with the dumbbells over your chest and palms facing each other.","Keep a slight, fixed bend in your elbows and your shoulder blades pinned together.","Open your arms in an arc to chest level, then close them as if hugging a tree.","Don't go so heavy that you have to bend your elbows and turn it into a press.","Don't let your arms drop below shoulder level."],aliases:[],origin:"new"},{id:"dumbbell-fly-incline",name_en:"Dumbbell Fly (Incline)",name_es:"Aperturas con mancuernas (inclinado)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the bench to a low incline and press the dumbbells up over your upper chest.","Keep your chest up and a slight, constant bend in your elbows.","Open your arms until you feel a stretch, then arc them back together over your collarbones.","Don't let the dumbbells drift back toward your head instead of out to the sides.","Take extra care on the lowering phase; that's where the shoulder is most exposed."],aliases:[],origin:"new"},{id:"cable-fly-low-to-high",name_en:"Cable Fly (Low to High)",name_es:"Aperturas en polea (de abajo hacia arriba)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Front Delts"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the pulleys at the lowest position and step forward between them.","Keep your torso upright, chest open, and elbows slightly bent.","Sweep your hands up in an arc to chin height, then lower slowly.","Don't pull with your biceps or shrug your shoulders on the way up.","Grab and release the handles with the stack at rest so you don't get pulled off balance."],aliases:[],origin:"new"},{id:"pec-deck-fly",name_en:"Pec Deck Fly",name_es:"Aperturas en máquina (pec deck)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Front Delts"],equipment:"machine",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Adjust the seat so the handles are at chest height with your elbows nearly straight.","Keep your back against the pad and shoulder blades together for the whole set.","Bring the handles together in front of your chest, squeeze for a second, and open under control.","Don't let your arms swing too far back on the stretch when the weight is heavy.","Set the machine's range-of-motion stop to limit how far back your arms go if needed."],aliases:[],origin:"new"},{id:"push-up",name_en:"Push-Up",name_es:"Flexiones",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts","Abs"],equipment:"bodyweight",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Place your hands slightly wider than your shoulders and extend your legs into a plank.","Keep a straight line from head to heels by squeezing your glutes and abs.","Lower your chest until it nearly touches the floor, then push back up to straight arms.","Don't let your hips sag or pike up.","If you lose body position, drop to your knees or elevate your hands to finish the set."],aliases:[],origin:"new"},{id:"push-up-incline",name_en:"Push-Up (Incline)",name_es:"Flexiones (inclinadas)",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"bodyweight",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Place your hands on a sturdy bench or box, slightly wider than your shoulders.","Keep your body straight as a board with your abs braced.","Bring your chest to the edge of the bench, then push back up to straight arms.","Don't let your head reach the bench before your chest does.","Make sure the bench or box can't slide before you put weight on it."],aliases:[],origin:"new"},{id:"push-up-decline",name_en:"Push-Up (Decline)",name_es:"Flexiones (declinadas)",body_region:"Chest",primary_muscles:["Upper Chest"],secondary_muscles:["Triceps","Front Delts","Abs"],equipment:"bodyweight",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Put your feet on a bench and your hands on the floor, slightly wider than your shoulders.","Brace your abs so your lower back doesn't sag.","Lower your face and chest toward the floor under control, then push back up.","Don't pike your hips up to shorten the range of motion.","Start with your feet only slightly elevated and raise them once your technique is solid."],aliases:[],origin:"new"},{id:"push-up-close-grip",name_en:"Push-Up (Close Grip)",name_es:"Flexiones (agarre cerrado)",body_region:"Chest",primary_muscles:["Triceps","Chest"],secondary_muscles:["Front Delts"],equipment:"bodyweight",movement_pattern:"push horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Place your hands under your shoulders or slightly narrower, fingers pointing forward.","Keep your elbows tucked to your ribs and your body in a straight line.","Lower until your chest brushes your hands, then push up by straightening your elbows.","Don't let your elbows flare out to the sides on the way down.","If your wrists feel loaded, widen your hands a little or use push-up handles."],aliases:[],origin:"new"},{id:"dip",name_en:"Dip",name_es:"Fondos en paralelas",body_region:"Chest",primary_muscles:["Chest"],secondary_muscles:["Triceps","Front Delts"],equipment:"bodyweight",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Mount the parallel bars with arms locked out and legs slightly behind you.","Lean your torso slightly forward and keep your shoulders down, away from your ears.","Lower until your shoulders are level with your elbows, then press back to the top.","Don't swing your legs to kip your way up.","Shorten the range or use assistance if you can't control the bottom position."],aliases:[],origin:"new"},{id:"machine-dip-assisted",name_en:"Machine Dip (Assisted)",name_es:"Fondos en máquina (asistidos)",body_region:"Chest",primary_muscles:["Chest","Triceps"],secondary_muscles:["Front Delts"],equipment:"machine",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Select the counterweight, kneel on the pad, and grip the bars with your arms locked out.","Keep your torso slightly forward and your shoulders down and back.","Lower under control until your elbows reach about 90 degrees, then press to full extension.","Remember more counterweight means more help; don't add it just to rep faster.","Step on and off the platform carefully, always holding onto the handles."],aliases:[],origin:"new"},{id:"dumbbell-shoulder-press",name_en:"Dumbbell Shoulder Press (Seated)",name_es:"Press de hombros con mancuernas (sentado)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"dumbbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit on a bench with a near-vertical back pad and bring the dumbbells to shoulder height.","Keep your back on the pad, core braced, and wrists stacked over your elbows.","Press the dumbbells up until they nearly touch, then lower to about ear level.","Don't arch your lower back to peel off the pad.","Get the dumbbells to your shoulders by resting them on your knees first."],aliases:[],origin:"existing"},{id:"db-oh-press-neutral-grip",name_en:"Dumbbell Shoulder Press (Neutral Grip)",name_es:"Press de hombros con mancuernas (agarre neutro)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"dumbbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Hold the dumbbells at shoulder height with your palms facing each other.","Keep your elbows in front of your body and your torso tight, without leaning back.","Press straight overhead, then lower under control to about chin level.","Don't flare your elbows out; with a neutral grip they should stay in front.","Use a bench with back support if you find yourself swaying as you press."],aliases:["neutral-grip-db-oh-press"],origin:"existing"},{id:"neutral-grip-pin-loaded-shoulder-press",name_en:"Machine Shoulder Press (Neutral Grip)",name_es:"Press de hombros en máquina (agarre neutro)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"machine",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Adjust the seat so the neutral handles sit at shoulder height.","Keep your back and head on the pad with your elbows slightly in front of your body.","Press up without locking your elbows, then lower slowly to shoulder height.","Don't let the weight stack rest between reps.","Check the seat height: starting too low puts your shoulder in a strained position."],aliases:[],origin:"existing"},{id:"wide-grip-shoulder-press-machine",name_en:"Machine Shoulder Press (Wide Grip)",name_es:"Press de hombros en máquina (agarre ancho)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"machine",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with the wide handles at ear height and your feet planted on the floor.","Keep your back against the pad and your wrists straight.","Press until your arms are nearly straight, then lower under control to the start.","Don't shrug your shoulders up toward your ears as you press.","Secure the weight pin and seat adjustment before every set."],aliases:[],origin:"existing"},{id:"plate-loaded-wide-grip-shoulder-press-machine",name_en:"Plate-Loaded Shoulder Press (Wide Grip)",name_es:"Press de hombros en máquina de discos (agarre ancho)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"plate-loaded",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the seat so you start with the wide handles just above your shoulders.","Keep your back and head on the pad and your core engaged.","Press the machine arms up, then lower slowly until you feel a stretch in your shoulders.","Don't arch your lower back to grind out the last reps.","Load plates evenly on both sides and strip them when you're done."],aliases:[],origin:"existing"},{id:"lateral-raises-machine",name_en:"Machine Lateral Raise",name_es:"Elevaciones laterales en máquina",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:[],equipment:"machine",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Adjust the seat so the machine's pivot lines up with your shoulder joints.","Rest your chest or back against the pad and keep your shoulders down.","Raise your arms out to the sides to shoulder height, then lower slowly.","Don't shrug with your traps to get extra height.","Choose a weight you can lower under control without the plates slamming down."],aliases:[],origin:"existing"},{id:"standing-db-lateral-raises",name_en:"Dumbbell Lateral Raise (Standing)",name_es:"Elevaciones laterales con mancuernas (de pie)",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:[],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Stand with feet hip-width apart and the dumbbells at your sides.","Lean slightly forward and keep a soft bend in your elbows.","Raise the dumbbells out to shoulder height, then take 2-3 seconds to lower them.","Don't swing your body to fling the dumbbells up.","Don't raise your hands above shoulder height if you feel pinching or discomfort."],aliases:[],origin:"existing"},{id:"db-60-y-raises",name_en:"Dumbbell Y-Raise (Incline)",name_es:"Elevaciones en Y con mancuernas (banco inclinado)",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:["Rear Delts","Upper Back"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Lie face down on a steep incline bench, dumbbells hanging and thumbs pointing up.","Keep your chest on the bench and your neck neutral throughout.","Raise your arms in a Y shape in front of your head to ear height, then lower slowly.","Don't shrug toward your ears or lift your chest off the bench.","Use light dumbbells: form breaks down quickly on this one when the load is too heavy."],aliases:[],origin:"existing"},{id:"barbell-overhead-press",name_en:"Barbell Overhead Press (Standing)",name_es:"Press militar con barra (de pie)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps","Upper Chest","Abs"],equipment:"barbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Unrack the bar at collarbone height with a grip slightly wider than your shoulders.","Squeeze your glutes and abs to keep your ribs down and your spine neutral.","Press the bar straight up, push your head through at the top, and lower to your collarbones.","Don't lean back so far that it becomes an incline press.","Set the rack hooks at chest height so you can unrack and rerack the bar safely."],aliases:[],origin:"new"},{id:"barbell-overhead-press-seated",name_en:"Barbell Overhead Press (Seated)",name_es:"Press militar con barra (sentado)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"barbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit on an upright bench under the racked bar with your feet planted.","Keep your back against the pad and your head neutral.","Lower the bar in front of your face to chin level, then press until your arms are straight.","Don't lower the bar behind your neck.","Set the hooks so you can unrack the bar without fully extending your arms to reach it."],aliases:[],origin:"new"},{id:"smith-machine-shoulder-press",name_en:"Smith Machine Shoulder Press (Seated)",name_es:"Press de hombros en máquina Smith (sentado)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"smith-machine",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Set an upright bench so the bar travels just in front of your face.","Keep your back on the pad and your wrists straight over your elbows.","Unrack the bar, lower it to your chin, and press up without locking out hard.","Don't jut your head forward toward the bar as you lower it.","Set the Smith machine safety stops at shoulder height."],aliases:[],origin:"new"},{id:"dumbbell-shoulder-press-standing",name_en:"Dumbbell Shoulder Press (Standing)",name_es:"Press de hombros con mancuernas (de pie)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps","Abs"],equipment:"dumbbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Stand with feet hip-width apart and the dumbbells resting at your shoulders.","Brace your abs and squeeze your glutes so your lower back doesn't arch.","Press the dumbbells overhead, then lower under control to ear level.","Don't drive the weight with your legs unless you're doing a deliberate push press.","Go lighter than the seated version: standing demands more stability."],aliases:[],origin:"new"},{id:"dumbbell-arnold-press",name_en:"Dumbbell Arnold Press",name_es:"Press Arnold con mancuernas",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Side Delts","Triceps"],equipment:"dumbbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with the dumbbells in front of your chin and palms facing you.","Keep your back on the pad and your elbows in front at the start.","Rotate your palms forward as you press up, and reverse the rotation as you lower.","Don't split the rotation and the press into two separate movements.","Use less weight than on a standard press so you can control the rotation."],aliases:[],origin:"new"},{id:"landmine-press",name_en:"Landmine Press (Single Arm)",name_es:"Press landmine (a una mano)",body_region:"Shoulders",primary_muscles:["Front Delts","Upper Chest"],secondary_muscles:["Triceps","Abs"],equipment:"barbell",movement_pattern:"push vertical",mechanic:"compound",laterality:"unilateral",posture_tips:["Hold the end of the bar at shoulder height in one hand with the opposite foot forward.","Keep your trunk tight and your shoulders square to the front, without twisting.","Press the bar up and forward to full arm extension, then lower it under control to your shoulder.","Don't lean away to the opposite side to press the bar.","Anchor the fixed end of the bar in a landmine unit or a secure corner."],aliases:[],origin:"new"},{id:"dumbbell-lateral-raise-seated",name_en:"Dumbbell Lateral Raise (Seated)",name_es:"Elevaciones laterales con mancuernas (sentado)",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:[],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Sit on the end of a bench with the dumbbells at your sides and feet flat.","Keep your torso tall and your shoulders down, away from your ears.","Raise your arms out to the sides to shoulder height, then lower slowly.","Don't rotate the dumbbells thumb-down as if pouring a jug of water.","Use a light weight that lets you pause briefly at the top."],aliases:[],origin:"new"},{id:"cable-lateral-raise",name_en:"Cable Lateral Raise (Single Arm)",name_es:"Elevaciones laterales en polea (a una mano)",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:[],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"unilateral",posture_tips:["Set the pulley low and grab the handle with the hand farthest from the machine.","Keep your torso steady by holding the machine with your free hand.","Raise your arm out to the side to shoulder height, then lower while resisting the cable.","Don't lean your trunk to cheat extra range of motion.","Start light: the cable keeps tension on the muscle through the whole rep."],aliases:[],origin:"new"},{id:"dumbbell-front-raise",name_en:"Dumbbell Front Raise",name_es:"Elevaciones frontales con mancuernas",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Upper Chest"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Stand with the dumbbells in front of your thighs and your palms facing you.","Keep your core braced and your elbows slightly bent.","Raise the dumbbells in front of you to shoulder height, then lower slowly.","Don't lean back to heave the weight up.","Stop at eye level; going higher adds no useful work."],aliases:[],origin:"new"},{id:"cable-front-raise",name_en:"Cable Front Raise",name_es:"Elevaciones frontales en polea",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Upper Chest"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Stand facing away from a low pulley with the rope or bar between your legs.","Keep your torso upright and your arms nearly straight.","Raise the handle in front of you to shoulder height, then lower while resisting the cable.","Don't let the cable pull you backward on the way down.","Take a wide enough stance to stay balanced against the cable's pull."],aliases:[],origin:"new"},{id:"dumbbell-rear-delt-fly",name_en:"Dumbbell Rear Delt Fly (Bent-Over)",name_es:"Pájaros con mancuernas (inclinado)",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Hinge at the hips with a flat back and let the dumbbells hang under your chest.","Keep your spine neutral and your neck in line with your torso.","Raise your arms out to the sides with a slight elbow bend, then lower slowly.","Don't over-squeeze your shoulder blades; the movement should come from the shoulder.","If keeping your back flat is hard, rest your forehead on an incline bench."],aliases:[],origin:"new"},{id:"dumbbell-rear-delt-fly-chest-supported",name_en:"Dumbbell Rear Delt Fly (Chest-Supported)",name_es:"Pájaros con mancuernas (pecho apoyado)",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Lie face down on an incline bench with the dumbbells hanging and palms facing each other.","Keep your chest glued to the bench and your chin neutral.","Raise your arms out to the sides to shoulder level, then lower under control.","Don't lift your chest off the bench to build momentum.","Use light dumbbells and put control ahead of load."],aliases:[],origin:"new"},{id:"cable-rear-delt-fly",name_en:"Cable Rear Delt Fly",name_es:"Pájaros en polea",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the pulleys at shoulder height and cross the cables, holding each with the opposite hand.","Keep your arms nearly straight and your chest open.","Pull your arms back and out until they line up with your body, then return slowly.","Don't bend your elbows and turn it into a row.","Take a stable step back before you start so you don't lose your balance."],aliases:[],origin:"new"},{id:"reverse-pec-deck-fly",name_en:"Reverse Pec Deck Fly",name_es:"Aperturas inversas en máquina (pec deck)",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back"],equipment:"machine",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Sit facing the pad with the handles at shoulder height.","Keep your chest on the pad and your shoulders down for the whole set.","Sweep your arms back in an arc to your body line, then return under control.","Don't pull with your traps by shrugging your shoulders.","Set the machine arms to the reverse position before you sit down."],aliases:[],origin:"new"},{id:"cable-face-pull",name_en:"Cable Face Pull (Rope)",name_es:"Face pull en polea (cuerda)",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back","Traps"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the pulley at face height or slightly higher and grip the rope with palms facing down.","Keep your torso tall and stable, without leaning back.","Pull the rope to your face, splitting your hands apart and rotating your shoulders out at the end.","Don't pull to your chest like a row; your hands should finish by your ears.","Use a moderate weight that lets you control the final rotation."],aliases:[],origin:"new"},{id:"band-pull-apart",name_en:"Band Pull-Apart",name_es:"Separaciones con banda elástica",body_region:"Shoulders",primary_muscles:["Rear Delts"],secondary_muscles:["Upper Back"],equipment:"band",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Hold the band in front of your chest, arms straight and hands shoulder-width apart.","Keep your ribs down and your shoulders away from your ears.","Pull your hands apart, bringing the band to your chest, then return without losing tension.","Don't bend your elbows to make it easier.","Inspect the band before use and throw it out if it has cracks or nicks."],aliases:[],origin:"new"},{id:"barbell-upright-row",name_en:"Barbell Upright Row",name_es:"Remo al mentón con barra",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:["Traps","Front Delts"],equipment:"barbell",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Hold the bar in front of your thighs with hands slightly wider than shoulder width.","Keep your torso upright and the bar close to your body.","Lift the bar by leading with your elbows to your lower chest, then lower slowly.","Don't pull the bar all the way to your chin with a narrow grip.","Stop at chest height if you feel discomfort at the top of your shoulder."],aliases:[],origin:"new"},{id:"cable-upright-row",name_en:"Cable Upright Row",name_es:"Remo al mentón en polea",body_region:"Shoulders",primary_muscles:["Side Delts"],secondary_muscles:["Traps","Front Delts"],equipment:"cable",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Face a low pulley with a straight bar or rope, gripping slightly wider than your shoulders.","Keep your back straight and your shoulders relaxed at the start.","Raise your elbows out to shoulder height, then lower while resisting the cable.","Don't lift your wrists higher than your elbows.","Use a moderate weight; the cable shouldn't pull you forward."],aliases:[],origin:"new"},{id:"push-up-pike",name_en:"Push-Up (Pike)",name_es:"Flexiones (en pica)",body_region:"Shoulders",primary_muscles:["Front Delts"],secondary_muscles:["Triceps","Upper Chest"],equipment:"bodyweight",movement_pattern:"push vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Place your hands and feet on the floor and lift your hips into an inverted V.","Keep your hips high and your back straight throughout.","Lower your head toward the floor between your hands, then push back up to straight arms.","Don't drop your hips and turn it into a regular push-up.","Lower slowly and don't put any weight on your head at the bottom."],aliases:[],origin:"new"}];export{e as default};
